pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        amount = bound(amount, 1, 100 ether);
        vm.deal(address(c), amount);
        address(c).call{value: 0}("");
        uint256 beforeBalance = address(c).balance;
        payable(address(c)).call{value: 0}(abi.encodeWithSelector(c.go.selector));
        uint256 afterBalance = address(c).balance;
        assertTrue(afterBalance < beforeBalance);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.deal(address(c), 1 ether); // give initial balance to cover any gas
        vm.deal(address(this), amount);
        vm.assume(amount <= address(this).balance);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
        // If the call to target 0xC8A60C... succeeds, the contract balance should be zero after transfer/selfdestruct
        if (success) {
            assertTrue(address(c).balance == 0, "Balance must be zero after successful go()");
        }
    }
}

