        vm.deal(sender, amount);
        vm.prank(sender);
        vm.deal(address(c), 0);
        address expectedOwner = c.owner();
        (bool success, ) = address(c).call{value: 0}("");
        if (success) {
            assertTrue(c.owner() == expectedOwner);
        }
    }
