pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, address(this).balance);

        address originalOwner = c.owner();

        // Try calling go() — it may revert
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));

        // The rule: If the call did not revert, then the owner remains the original deployer.
        if (success) {
            assertTrue(c.owner() == deployer);
        }
    }
}
